  _ = `หมวดรางวัล Steam ส่วนใหญ่ในปีนี้เหมาะสมกับเกมที่วางจำหน่ายในปี %1$s (หลังจากการเสนอชื่อเข้าชิงรางวัล Steam ในวันที่ %2$s) เนื่องจากเกมของคุณวางจำหน่ายก่อนวันที่ดังกล่าว จึงมีสิทธิ์เข้าชิงรางวัลเฉพาะในหมวด 'ทำงานด้วยใจรัก' เท่านั้น`,
