  _ = `ส่งออก XML`,
  _ = `ดาวน์โหลด CSV เป็นภาษาต่อแถว`,
  _ = `ดาวน์โหลด CSV เป็นช่องข้อมูลเนื้อหาต่อแถว`,
  _ = `ภาษาต่อแถว`,
  _ = `ภาษาต่อคอลัมน์`,
  _ = `โทเค็น, รายการภาษา`,
  _ = `นำเข้าไฟล์การแปลภาษา...`,
  _ = `นำเข้า...`,
  _ = `เลือกที่จะอัปโหลดตั้งแต่หนึ่งไฟล์ขึ้นไปเพื่อนำเข้าข้อความที่แปลไว้สำหรับชื่อ คำบรรยาย ข้อมูลสรุป และคำอธิบายของคุณ เราใช้ส่วนขยายไฟล์เพื่อพิจารณาว่าเป็นการนำเข้าไฟล์ XML หรือไฟล์ CSV หากเป็นไฟล์ XML เราจะใช้รหัสภาษา API ระบุไว้ท้ายชื่อไฟล์ก่อนหน้าส่วนขยายเพื่อระบุภาษาของเนื้อหาไฟล์ XML คุณควรเริ่มต้นด้วยการส่งออกไฟล์ CSV หรือไฟล์ XML เพื่อให้แน่ใจว่า คุณใช้ไฟล์ในรูปแบบที่ถูกต้อง`,
  _ = `การนำเข้าการแปลภาษาเสร็จสมบูรณ์ ภาษาดังต่อไปนี้ได้รับการอัปเดตแล้ว:  %1$s`,
  _ = `การนำเข้าการแปลภาษาเสร็จสมบูรณ์ ไม่มีการเปลี่ยนแปลงใด ๆ เกิดขึ้น`,
  _ = `เราไม่สามารถวิเคราะห์หรือจดจำแฟ้ม CSV นั้นได้`,
