  _ = `หน้าการลดราคานี้จะต้องมีอย่างน้อยอีกหนึ่งหมวดที่เป็นประเภทเดียวกันกับหมวดนี้ หมวดนี้มีไว้ให้ใช้เพียงครั้งเดียวในหน้าการลดราคาครั้งเดียวเท่านั้น คุณแน่ใจหรือไม่ว่าคุณต้องการหมวดประเภทนี้หลายหมวด?`,
  _ = `การเผยแพร่เสร็จสมบูรณ์แล้ว`,
  _ = `การเผยแพร่ล้มเหลวด้วยข้อผิดพลาดต่อไปนี้: `,
  _ = `บันทึกกิจกรรม`,
  _ = `บันทึกกิจกรรมสำเร็จเรียบร้อย`,
  _ = `ข้อผิดพลาดในการบันทึกกิจกรรม`,
  _ = `คำเตือนก่อนบันทึก`,
  _ = `กำลังบันทึกการเปลี่ยนแปลงกิจกรรม...`,
  _ = `บันทึกเสร็จสมบูรณ์เรียบร้อยแล้ว`,
  _ = `ลูกค้า Steam ควรเห็นการเปลี่ยนแปลงในทันที`,
